<?php $isEdit=!empty($schedule);$days=[1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo']; ?>
<div class="panel form-panel"><form method="post" action="<?= $isEdit?url('/schedules/'.$schedule['id'].'/update'):url('/schedules') ?>" class="form-grid"><?= csrf_field() ?>
<div class="field field-full"><label>Médico *</label><select name="doctor_id" required><option value="">Seleccionar</option><?php foreach($doctors as $d):?><option value="<?= $d['id'] ?>" <?= (int)old('doctor_id',$schedule['doctor_id']??0)===(int)$d['id']?'selected':'' ?>><?= e($d['name'].' · '.$d['specialty_name']) ?></option><?php endforeach;?></select></div>
<div class="field"><label>Día *</label><select name="weekday" required><option value="">Seleccionar</option><?php foreach($days as $n=>$name):?><option value="<?= $n ?>" <?= (int)old('weekday',$schedule['weekday']??0)===$n?'selected':'' ?>><?= e($name) ?></option><?php endforeach;?></select></div>
<div class="field"><label>Duración de cada cita *</label><select name="slot_minutes"><option value="20" <?= (int)old('slot_minutes',$schedule['slot_minutes']??30)===20?'selected':'' ?>>20 minutos</option><option value="30" <?= (int)old('slot_minutes',$schedule['slot_minutes']??30)===30?'selected':'' ?>>30 minutos</option><option value="45" <?= (int)old('slot_minutes',$schedule['slot_minutes']??30)===45?'selected':'' ?>>45 minutos</option><option value="60" <?= (int)old('slot_minutes',$schedule['slot_minutes']??30)===60?'selected':'' ?>>60 minutos</option></select></div>
<div class="field"><label>Hora inicial *</label><input type="time" name="start_time" value="<?= e(substr((string)old('start_time',$schedule['start_time']??'08:00'),0,5)) ?>" required></div><div class="field"><label>Hora final *</label><input type="time" name="end_time" value="<?= e(substr((string)old('end_time',$schedule['end_time']??'12:00'),0,5)) ?>" required><?php if(error('end_time')):?><small class="error-text"><?= e(error('end_time')) ?></small><?php endif;?></div>
<label class="switch-row field-full"><input type="checkbox" name="active" <?= (int)old('active',$schedule['active']??1)===1?'checked':'' ?>><span>Horario activo</span></label><div class="form-actions field-full"><a class="btn" href="<?= url('/schedules') ?>">Cancelar</a><button class="btn btn-primary">Guardar horario</button></div></form></div>
